SELECT

FROM voice_audit_log
WHERE voice_asset_id = #{voiceAssetId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
  AND actor_user_id = #{actorUserId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
ORDER BY ts DESC
LIMIT #{limit}
